// ============================================
// EXTRACT INVOICE DATA
// ============================================

const input = $input.first().json;
const body = input.body || input;

const eventData = body.event_data || body;
const invoice = eventData;

// Get subscription info from invoice
const subscriptionId = invoice.subscription;
const customerId = invoice.customer;
const attemptCount = invoice.attempt_count || 1;
const nextAttempt = invoice.next_payment_attempt;

return {
  event_id: body.event_id,
  invoice_id: invoice.id,
  customer_id: customerId,
  subscription_id: subscriptionId,
  amount_due: invoice.amount_due,
  currency: invoice.currency,
  attempt_count: attemptCount,
  next_attempt: nextAttempt ? new Date(nextAttempt * 1000).toISOString() : null,
  timestamp: new Date().toISOString()
};

// ============================================
// CHECK USER AND PREPARE GRACE PERIOD
// ============================================

const apiResponse = $input.first().json;
const invoiceData = $('Extract Invoice Data').first().json;

if (apiResponse.error || apiResponse.statusCode >= 400 || !apiResponse.data) {
  return {
    success: false,
    error: {
      code: 404,
      message: `User not found for Stripe customer: ${invoiceData.customer_id}`,
      status: 'USER_NOT_FOUND'
    },
    customer_id: invoiceData.customer_id
  };
}

const user = apiResponse.data || apiResponse;

// Calculate grace period (7 days from now)
const gracePeriodDays = 7;
const graceEndDate = new Date();
graceEndDate.setDate(graceEndDate.getDate() + gracePeriodDays);

// Determine notification day (J+0, J+3, J+6)
// For first failure, it's J+0
const daysSinceFirstFailure = 0; // Will be calculated from DB in real implementation
let notificationType = 'payment_failed_j0';
if (daysSinceFirstFailure >= 6) notificationType = 'payment_failed_j6';
else if (daysSinceFirstFailure >= 3) notificationType = 'payment_failed_j3';

return {
  success: true,
  user_id: user.id,
  discord_id: user.discord_id,
  guild_id: user.guild_id,
  customer_id: invoiceData.customer_id,
  subscription_id: invoiceData.subscription_id,
  invoice_id: invoiceData.invoice_id,
  amount_due: invoiceData.amount_due,
  currency: invoiceData.currency,
  attempt_count: invoiceData.attempt_count,
  grace_period_end: graceEndDate.toISOString(),
  grace_period_days: gracePeriodDays,
  notification_type: notificationType,
  event_id: invoiceData.event_id
};

