// ============================================
// PREPARE NOTIFICATION EVENT
// ============================================

const apiResponse = $input.first().json;
const userData = $('Check User & Prepare Grace').first().json;

const success = !apiResponse.error && apiResponse.statusCode !== 500;

// Format amount for display
const amountDisplay = (userData.amount_due / 100).toFixed(2);
const currencySymbol = userData.currency === 'eur' ? '€' : '$';

// Prepare notification event for chatbot-core
const notificationEvent = {
  event: 'subscription.payment_failed',
  guild_id: userData.guild_id,
  timestamp: new Date().toISOString(),
  data: {
    user_id: userData.user_id,
    discord_id: userData.discord_id,
    notification_type: userData.notification_type,
    amount_due: `${amountDisplay}${currencySymbol}`,
    grace_period_end: userData.grace_period_end,
    grace_period_days: userData.grace_period_days,
    attempt_count: userData.attempt_count
  }
};

return {
  event_id: userData.event_id,
  user_id: userData.user_id,
  discord_id: userData.discord_id,
  guild_id: userData.guild_id,
  grace_period_set: success,
  grace_period_end: userData.grace_period_end,
  notification_type: userData.notification_type,
  stream_name: 'learning:events:stream',
  event: notificationEvent
};
